// ------------------------------------------------------------
// Description / BTS pages
//   1. Collapsible sections (.dropdown-toggle + .description-dropdown)
//   2. Enlarged preview for images inside those sections
// ------------------------------------------------------------

// ------------------------------------------------------------
// 1. Collapsible sections
// ------------------------------------------------------------

// Each toggle points at its panel with aria-controls and starts in the
// state given by aria-expanded, so the HTML decides what is open.
function setupDropdowns(): void {

    const toggles = document.querySelectorAll<HTMLButtonElement>('.dropdown-toggle');

    toggles.forEach((toggle) => {

        const panel = document.getElementById(
            toggle.getAttribute('aria-controls') ?? ''
        );

        if (!panel) {
            return;
        }

        const setOpen = (open: boolean): void => {
            toggle.setAttribute('aria-expanded', String(open));
            panel.hidden = !open;
        };

        setOpen(toggle.getAttribute('aria-expanded') === 'true');

        toggle.addEventListener('click', () => {
            setOpen(toggle.getAttribute('aria-expanded') !== 'true');
        });
    });
}

// ------------------------------------------------------------
// 2. Enlarged image preview
//
//   Mouse:    hover shows the preview, moving away hides it.
//             Clicking pins it open.
//   Keyboard: focusing an image shows it, moving focus away hides it.
//   Touch:    tapping pins the preview open.
//   A pinned preview closes on click, tap or Escape.
// ------------------------------------------------------------

function setupImagePreview(): void {

    const thumbs = document.querySelectorAll<HTMLImageElement>('.description-dropdown img');

    if (thumbs.length === 0) {
        return;
    }

    const overlay = document.createElement('div');
    overlay.className = 'image-preview';
    overlay.setAttribute('aria-hidden', 'true');

    const enlarged = document.createElement('img');
    overlay.append(enlarged);

    document.body.append(overlay);

    // True once the preview has been opened by a click or tap
    let pinned = false;

    // The thumbnail currently shown enlarged (null when closed)
    let current: HTMLImageElement | null = null;

    // Space kept free around the enlarged image, and its largest width
    const PREVIEW_MARGIN = 64;
    const PREVIEW_MAX_WIDTH = 1400;

    // Scales the preview up (or down) to fill the screen. CSS max-width
    // can only shrink an image, so small images such as the pixel-art
    // GIFs would otherwise appear smaller than their thumbnails.
    function fitPreview(): void {

        if (!current || !current.naturalWidth || !current.naturalHeight) {
            return;
        }

        const maxWidth = Math.min(window.innerWidth - PREVIEW_MARGIN, PREVIEW_MAX_WIDTH);
        const maxHeight = window.innerHeight - PREVIEW_MARGIN;

        let scale = Math.min(
            maxWidth / current.naturalWidth,
            maxHeight / current.naturalHeight
        );

        // Pixel art: whole-number scales keep every pixel the same size
        if (current.classList.contains('pixelated') && scale >= 1) {
            scale = Math.floor(scale);
        }

        enlarged.style.width = `${Math.round(current.naturalWidth * scale)}px`;
        enlarged.style.height = `${Math.round(current.naturalHeight * scale)}px`;
    }

    function show(source: HTMLImageElement, pin: boolean): void {

        enlarged.src = source.currentSrc || source.src;
        enlarged.alt = source.alt;
        enlarged.classList.toggle('pixelated', source.classList.contains('pixelated'));

        current = source;
        fitPreview();

        pinned = pin;

        overlay.classList.toggle('pinned', pin);
        overlay.classList.add('active');
    }

    function hide(): void {

        pinned = false;
        current = null;

        overlay.classList.remove('active', 'pinned');
    }

    thumbs.forEach((thumb) => {

        // Make the thumbnail reachable and operable from the keyboard
        thumb.tabIndex = 0;
        thumb.setAttribute('role', 'button');
        thumb.setAttribute('aria-label', `Enlarge: ${thumb.alt}`);

        thumb.addEventListener('pointerenter', (event: PointerEvent) => {

            if (event.pointerType === 'mouse' && !pinned) {
                show(thumb, false);
            }
        });

        thumb.addEventListener('pointerleave', (event: PointerEvent) => {

            if (event.pointerType === 'mouse' && !pinned) {
                hide();
            }
        });

        // Keyboard focus only (a mouse click also focuses, but is handled below)
        thumb.addEventListener('focus', () => {

            if (!pinned && thumb.matches(':focus-visible')) {
                show(thumb, false);
            }
        });

        thumb.addEventListener('blur', () => {

            if (!pinned) {
                hide();
            }
        });

        thumb.addEventListener('click', () => show(thumb, true));

        thumb.addEventListener('keydown', (event: KeyboardEvent) => {

            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                show(thumb, true);
            }
        });
    });

    overlay.addEventListener('click', hide);

    // Keep the enlarged image fitted if the window is resized or rotated
    window.addEventListener('resize', fitPreview);

    document.addEventListener('keydown', (event: KeyboardEvent) => {

        if (event.key === 'Escape') {
            hide();
        }
    });
}

// ------------------------------------------------------------
// Start
// ------------------------------------------------------------

document.addEventListener('DOMContentLoaded', () => {
    setupDropdowns();
    setupImagePreview();
});